public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] a = new int[n];

    for (int i = 0; i < n; i++) {
        a[i] = sc.nextInt();
    }

    sc.close();
    long mod = 998244353;
    long[] dp = new long[n];
    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        if (dp[i] > 0) {
            for (int j = i + a[i]; j < n; j += a[i]) {
                dp[j] = (dp[j] + dp[i]) % mod;
            }
        }
    }

    long ans = 0;
    for (int i = 0; i < n; i++) {
        ans = (ans + dp[i]) % mod;
    }

    System.out.println(ans);
}
